/**
 * Encode a LAN IP address to a pairing word or base36 code.
 * @param {string} ip - IPv4 address string
 * @returns {string} A word (for 192.168.0-1.x) or 6-char base36 code
 */
export function encodeIP(ip) {
  const parts = ip.split('.').map(Number);
  if (parts.length !== 4 || parts.some(p => isNaN(p) || p < 0 || p > 255)) {
    return '';
  }
  if (parts[0] === 192 && parts[1] === 168 && parts[2] <= 1) {
    const index = parts[2] * 256 + parts[3];
    if (index < PAIRING_WORDS.length) {
      return PAIRING_WORDS[index];
    }
  }
  // Fallback: base36 encode full IP
  const num = ((parts[0] << 24) | (parts[1] << 16) | (parts[2] << 8) | parts[3]) >>> 0;
  return num.toString(36).toUpperCase().padStart(6, '0');
}

/**
 * Decode a pairing word or base36 code back to an IP address.
 * @param {string} input - A pairing word or 6-char code
 * @returns {string|null} IPv4 address or null if invalid
 */
export function decodeInput(input) {
  const clean = (input || '').trim().toLowerCase();
  if (!clean) return null;

  // Try word lookup
  const index = PAIRING_WORDS.indexOf(clean);
  if (index >= 0) {
    const octet2 = Math.floor(index / 256);
    const octet3 = index % 256;
    return `192.168.${octet2}.${octet3}`;
  }

  // Try base36 decode
  try {
    const num = parseInt(clean, 36);
    if (isNaN(num) || num < 0 || num > 0xFFFFFFFF) return null;
    const o1 = (num >>> 24) & 0xFF;
    const o2 = (num >>> 16) & 0xFF;
    const o3 = (num >>> 8) & 0xFF;
    const o4 = num & 0xFF;
    return `${o1}.${o2}.${o3}.${o4}`;
  } catch {
    return null;
  }
}
